-- Seed — Partidos políticos e Parlamentares (Câmara dos Deputados + Senado
-- Federal) — .dev/specs/entities/data-model.md
--
-- Pedido do usuário: "crie um seed com todos os partidos e parlamentares
-- complementando todas as informações que vc conseguir na internet".
--
-- Fonte dos dados: consultado ao vivo nesta sessão contra as APIs de dados
-- abertos oficiais do Congresso Nacional — nenhum dado inventado/estimado,
-- mesma premissa já aplicada em todo o restante do projeto ("nunca fabricar
-- dado que não tem fonte real", ver CLAUDE.md):
--   - Câmara dos Deputados: https://dadosabertos.camara.leg.br/api/v2/deputados
--     (legislatura atual, 512 deputados retornados) e /api/v2/partidos
--     (partidos com representação atual na Câmara).
--   - Senado Federal: https://legis.senado.leg.br/dadosabertos/senador/lista/atual
--     (81 senadores em exercício).
--
-- Escopo: 21 partidos com representação federal ativa (Câmara e/ou Senado,
-- legislatura corrente) + 512 deputados federais + 81 senadores = 593
-- parlamentares. Cada parlamentar recebe 3 entity_tags (office/party/state),
-- todos direto dos mesmos endpoints oficiais — nenhuma inferência local.
--
-- ⚠️ Deliberadamente FORA deste seed, por não ter fonte oficial verificável
-- em lote (mesma cautela já aplicada em todo o projeto a qualquer dado sem
-- fonte confirmada):
--   - Contas em redes sociais (entity_accounts) — não populadas. Handles do
--     Twitter/Instagram/etc. de 593 pessoas não têm uma API oficial em lote
--     confiável, e um handle errado quebraria o vínculo com
--     bw_query_top_authors (ver author-linking.md) silenciosamente. Ficam
--     para cadastro manual (tela /admin/entities) ou uma futura rotina de
--     enriquecimento, nunca inventados aqui.
--   - `influence_level` (entities) — campo explicitamente "manual e
--     subjetiva" por design (ver data-model.md); não preenchido por um
--     seed automatizado.
--   - `political_spectrum`/`ideology` (entity_tags) — classificação
--     contestável/subjetiva; não incluída neste seed para não apresentar
--     como fato uma opinião não verificada nesta sessão. Fica para
--     classificação manual pelo admin.
--   - Partidos registrados no TSE sem nenhum parlamentar federal eleito
--     atualmente (ex: PCO, PSTU, PCB, UP, PMB, PRTB, DC) — não incluídos:
--     a lista abaixo reflete só partidos com representação federal
--     confirmada nas duas fontes oficiais acima nesta data. Adicionar os
--     demais é um INSERT direto quando/se forem relevantes para algum
--     cliente.
--
-- Idempotência: usa `on conflict do nothing` nas 3 tabelas — pode ser
-- reexecutado sem duplicar linhas se rodado mais de uma vez sobre o mesmo
-- ambiente (a chave de conflito de `entities` é o `id` explícito gerado
-- nesta sessão, fixo neste arquivo).

